const item = $input.first().json || {};
const procData = $('Evaluar y Crear Linea MVPlay').item.json;

return [{
  json: {
    status: 'created',
    trial_number: procData.trial_number,
    username: procData.username,
    password: procData.password,
    dns: procData.dns,
    dns_smart_tv: procData.dns_smart_tv,
    m3u_url: procData.m3u_url,
    instrucciones: procData.instrucciones
  }
}];

return [{
  json: {
    status: 'limit_reached',
    message: 'El cliente ya ha recibido el límite máximo de 2 pruebas gratuitas permitidas.'
  }
}];

const convData = $input.first().json || {};
const contact = convData.meta?.sender || convData.sender || {};
const customAttr = contact.custom_attributes || {};

// Trigger input data
let triggerItem = {};
try {
  triggerItem = $('Execute Workflow Trigger').first().json || {};
} catch (e) {
  try { triggerItem = $input.first().json || {}; } catch(e2) {}
}

let contact_name = triggerItem.contact_name || triggerItem.name || contact.name || '';
let email = triggerItem.email || contact.email || '';
let phone = (triggerItem.phone || contact.phone_number || '').toString();
const query = (triggerItem.query || '').toString();

if (query) {
  const nameMatch = query.match(/(?:contact_name|nombre|name)\s*:\s*([^,\n]+)/i);
  if (nameMatch && !contact_name) contact_name = nameMatch[1].trim();

  const emailMatch = query.match(/(?:email|correo)\s*:\s*([^,\n\s]+)/i);
  if (emailMatch && !email) email = emailMatch[1].trim();

  const phoneMatch = query.match(/(?:phone|telefono|tel|celular)\s*:\s*([0-9+]+)/i);
  if (phoneMatch && !phone) phone = phoneMatch[1].trim();
}

if (!contact_name) contact_name = 'Cliente';
const fullName = contact_name.trim();

// 1. Username formatting: NombreApellido without spaces or accents
let formattedUsername = '';
if (fullName && fullName.toLowerCase() !== 'cliente') {
  // Normalize accents and remove special characters
  const cleanName = fullName
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9\s]/g, '')
    .trim();
  const words = cleanName.split(/\s+/);
  if (words.length >= 2) {
    formattedUsername = words[0] + words[1];
  } else if (words.length === 1 && words[0].length >= 3) {
    formattedUsername = words[0];
  }
}

// 2. Password formatting: phone number digits
const cleanPhone = phone.replace(/\D/g, '');
let formattedPassword = cleanPhone;

// 3. Reseller Notes: ONLY full name (no email, no phone)
const resellerNotes = fullName;

const account_id = triggerItem.account_id || 1;
const conversation_id = triggerItem.conversation_id;

// 4. Check trial history
const trial1 = customAttr.tvtotal_trial_1_id || customAttr.trial_1_id;
const trial2 = customAttr.tvtotal_trial_2_id || customAttr.trial_2_id;

let trial_number = 1;
if (!trial1) {
  trial_number = 1;
} else if (!trial2) {
  trial_number = 2;
} else {
  // Limit reached
  return [{
    json: {
      can_create: false,
      trial_number: 3,
      account_id,
      conversation_id,
      status: 'limit_reached',
      message: 'El cliente ya ha recibido el límite máximo de 2 pruebas gratuitas permitidas.'
    }
  }];
}

// 5. Call MVPlay API with fallback
const apiUrl = 'http://1395.cooteg.ch:2095/pooqkDEG/reseller/index.php';
const apiKey = 'ace3cacdfd48afdec756ec214ec0793f';

async function createMvplayLine(u, p, notes) {
  const bodyParams = new URLSearchParams();
  bodyParams.append('api_key', apiKey);
  bodyParams.append('action', 'create_line');
  bodyParams.append('package', '2'); // Demo 3 Horas TVTotal24
  bodyParams.append('trial', '1');
  bodyParams.append('username', u || '');
  bodyParams.append('password', p || '');
  bodyParams.append('reseller_notes', notes || '');

  const resp = await fetch(apiUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': 'Mozilla/5.0'
    },
    body: bodyParams.toString()
  });
  return await resp.json();
}

let apiResult = null;
try {
  apiResult = await createMvplayLine(formattedUsername, formattedPassword, resellerNotes);
  if (apiResult.status !== 'STATUS_SUCCESS') {
    // Retry with auto-generated username & password if rejected
    apiResult = await createMvplayLine('', '', resellerNotes);
  }
} catch (err) {
  // Retry fallback
  try {
    apiResult = await createMvplayLine('', '', resellerNotes);
  } catch (err2) {}
}

const isSuccess = apiResult && apiResult.status === 'STATUS_SUCCESS';
const lineData = apiResult?.data || {};

const finalUsername = lineData.username || formattedUsername || 'demo';
const finalPassword = lineData.password || formattedPassword || 'demo123';
const lineId = lineData.id || 1;

// Prepare updated custom attributes for Chatwoot
const updatedCustomAttr = { ...customAttr };
const nowIso = new Date().toISOString();

if (trial_number === 1) {
  updatedCustomAttr.tvtotal_trial_1_id = lineId;
  updatedCustomAttr.tvtotal_trial_1_username = finalUsername;
  updatedCustomAttr.tvtotal_trial_1_password = finalPassword;
  updatedCustomAttr.tvtotal_trial_1_created_at = nowIso;
} else {
  updatedCustomAttr.tvtotal_trial_2_id = lineId;
  updatedCustomAttr.tvtotal_trial_2_username = finalUsername;
  updatedCustomAttr.tvtotal_trial_2_password = finalPassword;
  updatedCustomAttr.tvtotal_trial_2_created_at = nowIso;
}

return [{
  json: {
    can_create: isSuccess,
    trial_number,
    username: finalUsername,
    password: finalPassword,
    line_id: lineId,
    account_id,
    conversation_id,
    contact_id: contact.id,
    custom_attributes: updatedCustomAttr,
    dns: 'http://wk.mvpl.uk:2082',
    dns_smart_tv: 'http://cdn01link.uk:2095',
    m3u_url: `http://wk.mvpl.uk:2082/get.php?username=${finalUsername}&password=${finalPassword}&type=m3u_plus&output=ts`,
    instrucciones: 'Para Firestick / Android TV / Móviles Android: Abre la app TotalTV, selecciona el panel TOTALTV LATINA e introduce tu usuario y contraseña. Para Smart TV / Apple: Usa Smarters Player Lite con el DNS http://wk.mvpl.uk:2082'
  }
}];
